import { createSelector } from 'reselect';
const getWidgetsById = state => state.widgets.byId;
const getTenantFeatures = state => state.tenants.byId[state.tenantId].features;
const getFocusActive = state => state.ui.focusActive;

export const getVisibleWidgetIds = createSelector(
  [getWidgetsById, getTenantFeatures, getFocusActive],
  (widgets, features, focusActive) =>
    Object.keys(widgets).filter(id => widgets[id].visible && features[id]?.enabled && (!focusActive || !widgets[id].requiresFocus))
);
```
